# PTX source for cross‑entropy loss (fp16 inputs, fp32 accumulation)
PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry cross_entropy(
    .param .u64 pred_ptr,
    .param .u64 targ_ptr,
    .param .u64 out_ptr,
    .param .u32 batch_sz,
    .param .u32 cls_cnt
)
{
    // -------------------------------------------------
    // Registers
    // -------------------------------------------------
    .reg .b64 pred;
    .reg .b64 targ;
    .reg .b64 out;
    .reg .u32 batch;
    .reg .u32 classes;
    .reg .u32 tid;
    .reg .u32 i;

    .reg .b64 addr;
    .reg .b64 elem_off;
    .reg .b64 byte_off;

    .reg .u16 half_val;
    .reg .f32 f_val;
    .reg .f32 f_max;
    .reg .f32 f_sum;
    .reg .f32 f_tmp;
    .reg .f32 f_exp;
    .reg .f32 f_log2;
    .reg .f32 f_log;
    .reg .f32 f_log_sum;
    .reg .f32 f_target;
    .reg .f32 f_target_pred;
    .reg .f32 f_loss;

    .reg .s32 target_idx;

    // -------------------------------------------------
    // Load kernel parameters
    // -------------------------------------------------
    ld.param.u64 pred, [pred_ptr];
    ld.param.u64 targ, [targ_ptr];
    ld.param.u64 out,  [out_ptr];
    ld.param.u32 batch, [batch_sz];
    ld.param.u32 classes, [cls_cnt];

    // -------------------------------------------------
    // Compute thread (sample) id
    // -------------------------------------------------
    mov.u32 tid, %ctaid.x;               // one thread per sample

    // if tid >= batch -> exit
    setp.ge.u32 p_exit, tid, batch;
    @p_exit ret;

    // -------------------------------------------------
    // Load target class (stored as fp16, convert to int)
    // -------------------------------------------------
    mul.wide.u32 byte_off, tid, 2;       // each fp16 = 2 bytes
    add.u64 addr, targ, byte_off;
    ld.global.nc.u16 half_val, [addr];
    cvt.f32.f16 f_target, half_val;
    cvt.rzi.f32.s32 target_idx, f_target; // integer class index

    // -------------------------------------------------
    // 1) Compute max value of logits for this sample
    // -------------------------------------------------
    mov.f32 f_max, -3.4028235e38;        // -FLT_MAX
    mov.u32 i, 0;

max_loop:
    setp.ge.u32 p_done, i, classes;
    @p_done bra sum_loop;

    // address of predictions[tid, i]
    mul.wide.u32 elem_off, tid, classes; // row offset in elements
    add.u32 elem_off, elem_off, i;       // + column
    mul.wide.u32 byte_off, elem_off, 2; // *2 bytes per half
    add.u64 addr, pred, byte_off;
    ld.global.nc.u16 half_val, [addr];
    cvt.f32.f16 f_val, half_val;
    max.f32 f_max, f_max, f_val;

    add.u32 i, i, 1;
    bra max_loop;

    // -------------------------------------------------
    // 2) Compute sum of exp(logits - max)
    // -------------------------------------------------
sum_loop:
    setp.ge.u32 p_done2, i, classes;
    @p_done2 bra log_compute;

    mul.wide.u32 elem_off, tid, classes;
    add.u32 elem_off, elem_off, i;
    mul.wide.u32 byte_off, elem_off, 2;
    add.u64 addr, pred, byte_off;
    ld.global.nc.u16 half_val, [addr];
    cvt.f32.f16 f_val, half_val;
    sub.f32 f_val, f_val, f_max;               // logits - max

    // exp(x) ≈ 2^(x / ln2)
    mul.f32 f_tmp, f_val, 1.442695040889;      // 1/ln2
    ex2.approx.f32 f_exp, f_tmp;               // 2^(x/ln2) ≈ e^x

    add.f32 f_sum, f_sum, f_exp;

    add.u32 i, i, 1;
    bra sum_loop;

    // -------------------------------------------------
    // 3) Compute log‑sum‑exp = max + log(sum)
    // -------------------------------------------------
log_compute:
    // log(sum) = ln2 * log2(sum)
    lg2.approx.f32 f_log2, f_sum;
    mul.f32 f_log, f_log2, 0.69314718056;      // ln2
    add.f32 f_log_sum, f_max, f_log;           // log‑sum‑exp

    // -------------------------------------------------
    // 4) Load logit of the correct class
    // -------------------------------------------------
    mul.wide.u32 elem_off, tid, classes;
    add.u32 elem_off, elem_off, target_idx;
    mul.wide.u32 byte_off, elem_off, 2;
    add.u64 addr, pred, byte_off;
    ld.global.nc.u16 half_val, [addr];
    cvt.f32.f16 f_target_pred, half_val;

    // -------------------------------------------------
    // 5) loss_i = -(target_logit - log_sum_exp) = log_sum_exp - target_logit
    // -------------------------------------------------
    sub.f32 f_loss, f_log_sum, f_target_pred;

    // -------------------------------------------------
    // 6) Atomic add to global accumulator (fp32)
    // -------------------------------------------------
    atom.global.add.f32 [out], f_loss;

    ret;
}
'''

import torch
import torch.nn as nn

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        # ptx_load is provided by the harness
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, predictions: torch.Tensor, targets: torch.Tensor):
        """
        predictions: FP16 tensor of shape (B, C)
        targets:    FP16 tensor of shape (B,) where each value encodes the class index
        Returns:    FP16 scalar loss (mean cross‑entropy)
        """
        batch = predictions.shape[0]
        classes = predictions.shape[1]

        # allocate a FP32 scalar for the summed loss, initialise to zero
        sum_tensor = torch.zeros(1, dtype=torch.float32, device=predictions.device)

        # launch one thread per sample
        grid = (batch, 1, 1)
        block = (1, 1, 1)

        args = [
            predictions.data_ptr(),
            targets.data_ptr(),
            sum_tensor.data_ptr(),
            int(batch),
            int(classes)
        ]

        ptx_launch(self.module, "cross_entropy", grid, block, args)

        # compute mean and cast to FP16
        loss_mean = (sum_tensor.item() / batch)
        return torch.tensor(loss_mean, dtype=torch.float16, device=predictions.device)
